-- Test types, like VWO: A/B, split URL and multivariate (MVT).
--   ab         variants change the page with JS / CSS (as before)
--   split_url  each variant is a different URL; the SDK redirects visitors to it
--   mvt        sections (factors) with versions (levels); every combination is a variant,
--              generated by the dashboard from `factors`
-- Multivariate tests were out of scope for v1 (PRODUCT_SPEC §11); decision #27 brings them in.

alter table public.experiments add column type text not null default 'ab'
  check (type in ('ab', 'split_url', 'mvt'));
-- MVT: [{ "name": "Headline", "levels": [{ "name": "Original", "js": "", "css": "" }, …] }, …]
alter table public.experiments add column factors jsonb not null default '[]';
alter table public.variants add column url text
  check (url is null or (url ~ '^https?://' and char_length(url) <= 2048));

-- Duplicates keep the type, factors and variant URLs.
create or replace function public.duplicate_experiment(p_experiment uuid)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_src public.experiments;
  v_id uuid;
  v_base text;
  v_key text;
begin
  select * into v_src from public.experiments where id = p_experiment;
  if not found then
    raise exception 'Experiment not found.';
  end if;

  v_base := left(v_src.key, 56) || '-copy';
  for attempt in 1..50 loop
    v_key := case when attempt = 1 then v_base else v_base || '-' || attempt end;
    exit when not exists (
      select 1 from public.experiments where project_id = v_src.project_id and key = v_key
    );
    v_key := null;
  end loop;
  if v_key is null then
    raise exception 'Could not find a free experiment key. Rename some copies first.';
  end if;

  insert into public.experiments
    (project_id, key, name, hypothesis, traffic_pct, targeting, primary_metric_id, planned_sample, plan, preview_url, type, factors)
  values
    (v_src.project_id, v_key, v_src.name || ' (copy)', v_src.hypothesis, v_src.traffic_pct,
     v_src.targeting, v_src.primary_metric_id, v_src.planned_sample, v_src.plan, v_src.preview_url,
     v_src.type, v_src.factors)
  returning id into v_id;

  insert into public.variants (experiment_id, key, name, weight, js, css, url)
  select v_id, key, name, weight, js, css, url from public.variants where experiment_id = p_experiment;

  insert into public.experiment_metrics (experiment_id, metric_id, role, "limit")
  select v_id, metric_id, role, "limit" from public.experiment_metrics where experiment_id = p_experiment;

  return v_id;
end;
$$;

-- The SDK config also carries each variant's URL (split URL tests).
create or replace function public.sdk_config_source(p_public_key text, p_preview uuid default null)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'experiments', case when public.workspace_over_limit(p.workspace_id) then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'key', e.key,
        'preview', e.status <> 'live',
        'name', e.name,
        'trafficPct', e.traffic_pct,
        'targeting', e.targeting,
        'metricIds', (
          select coalesce(jsonb_agg(em.metric_id), '[]'::jsonb)
          from public.experiment_metrics em where em.experiment_id = e.id
        ) || case when e.primary_metric_id is null then '[]'::jsonb
                  else jsonb_build_array(e.primary_metric_id) end,
        'variants', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'key', v.key, 'name', v.name, 'weight', v.weight, 'js', v.js, 'css', v.css, 'url', v.url
          ) order by v.key), '[]'::jsonb)
          from public.variants v where v.experiment_id = e.id
        )
      ) order by e.created_at)
      from public.experiments e
      where e.project_id = p.id
        and (e.status = 'live' or (p_preview is not null and e.preview_token = p_preview))
    ), '[]'::jsonb) end,
    'segments', coalesce((
      select jsonb_object_agg(s.id, s.rules) from public.segments s where s.project_id = p.id
    ), '{}'::jsonb),
    'metrics', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', m.id, 'eventKey', m.event_key, 'source', m.source, 'sourceConfig', m.source_config
      ))
      from public.metrics m where m.project_id = p.id
    ), '[]'::jsonb),
    'settings', p.settings
  )
  from public.projects p
  where p.public_key = p_public_key;
$$;
